mapper.select:
SELECT t.user_id, t.username, t.nickname, t.phone, t.email, t.user_status FROM ( SELECT u.id AS user_id, u.username, u.nickname, u.phone, u.email, u.status AS user_status, ROW_NUMBER() OVER (ORDER BY u.username) AS rank_num FROM sys_user u WHERE u.deleted = 0 AND u.id NOT IN ( SELECT ud.user_id FROM sys_user_dept ud WHERE ud.dept_id = #{deptId} )
AND (u.username LIKE CONCAT('%', CONCAT(#{username}, '%')) OR u.nickname LIKE CONCAT('%', CONCAT(#{username}, '%')))
) t WHERE t.rank_num <= 100 ORDER BY t.username
